mapper.insert:
INSERT INTO stocks.stock_data(symbol, bucket_start, "open", high, low, "close", volume) SELECT DISTINCT ON (symbol, bucket_start) symbol, bucket_start, "open", high, low, "close", volume FROM ( VALUES
(#{r.symbol}, #{t.tsKst,jdbcType=TIMESTAMP}, #{t.open}, #{t.high}, #{t.low}, #{t.close}, #{t.volume}),
) AS v(symbol, bucket_start, "open", high, low, "close", volume) ORDER BY symbol, bucket_start ON CONFLICT (symbol, bucket_start) DO UPDATE SET "open" = EXCLUDED."open", high = EXCLUDED.high, low = EXCLUDED.low, "close" = EXCLUDED."close", volume = EXCLUDED.volume

mapper.select:
SELECT
    symbol,
    (bucket_start AT TIME ZONE 'Asia/Seoul') AS bucketStart,
    "open" AS open, high, low, "close" AS close, volume
FROM stocks.stock_data
WHERE symbol = #{req.symbol}
 AND bucket_start >= #{req.from} 
   AND bucket_start <  #{req.to} 
    ORDER BY bucket_start
